func constructXsDoubleRe() *regexp.Regexp {
	doubleRep := "((\\+|-)?([0-9]+(\\.[0-9]*)?|\\.[0-9]+)([Ee](\\+|-)?[0-9]+)?|-?INF|NaN)"
	pattern := aascommon.Concat(
		"^",
		doubleRep,
		"$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

